1	/**
2	 * The objective ledger: what the operator asked for, and how far the work has got against it.
3	 *
4	 * The plan (`update_plan`) is the agent's own roadmap and may be coarser than the request. The ledger keeps the
5	 * request itself — verbatim — and the acceptance criteria seeded from it, so a reduced plan can never stand in for
6	 * them. Requirements change state only with evidence, scope changes are recorded explicitly, operator steering is
7	 * kept until applied, and verifier attempts are remembered against the exact workspace inputs they ran on.
8	 *
9	 * Pure data and pure functions; the agent owns persistence and presentation.
10	 */
11	import { createHash } from "node:crypto";
12	import type { VerificationStatus } from "./turn.js";
13	import type { CanonicalCapability } from "./capabilities.js";
14	import { isFilteredVerifierCommand } from "../tester.js";
15	import { createTracking, ExecutionTracker, normalizeTracking, type ExecutionTracking } from "./execution_tracking.js";
16	
17	export const LEDGER_VERSION = 1;
18	export const PINNED_LEDGER_PREFIX = "[Objective Ledger - pinned by Nexus; never summarised]";
19	export const STEERING_PREFIX = "[Operator steering";
20	/** Objectives longer than this are pinned in full only while the original message has left the context. */
21	export const MAX_PINNED_OBJECTIVE_CHARS = 24_000;
22	/** Operator follow-ups and steering pinned verbatim, newest first, up to this many characters (or the block's budget). */
23	const MAX_PINNED_OPERATOR_CHARS = 12_000;
24	const MAX_REQUIREMENT_TEXT = 240;
25	const MAX_EVIDENCE_ITEMS = 6;
26	const MAX_EVIDENCE_CHARS = 300;
27	
28	export type RequirementStatus = "open" | "in_progress" | "implemented" | "verified" | "blocked" | "descoped";
29	/** Statuses that need no further work in this task. `blocked` is terminal for the turn but never "done". */
30	export const DONE_STATUSES: ReadonlySet<RequirementStatus> = new Set(["implemented", "verified", "descoped"]);
31	
32	/**
33	 * Done for the purpose of completion. Descoping reduces what the operator asked for, so only the operator can make
34	 * it count: a descoped operator or steering requirement stays unresolved until `operatorAccepted` is set (by the
35	 * operator's `/requirements accept`), while a sub-requirement the agent added itself may be descoped freely.
36	 */
37	export function requirementDone(r: Requirement): boolean {
38	  if (r.status === "implemented" || r.status === "verified") return true;
39	  return r.status === "descoped" && (r.source === "model" || r.operatorAccepted === true);
40	}
41	
42	export interface Requirement {
43	  id: string;
44	  /** Heading line (capped), for lists. */
45	  text: string;
46	  /** The requirement's complete wording from the operator's message (nested items included), never truncated. */
47	  detail?: string;
48	  status: RequirementStatus;
49	  /** Where it came from: the operator's objective, operator steering, or the model (added sub-requirement). */
50	  source: "objective" | "steering" | "model";
51	  /** Implementation and validation evidence (file paths, commands, test names). */
52	  evidence: string[];
53	  /** Reason for blocked/descoped; required for both. */
54	  note?: string;
55	  /** The operator accepted this requirement's descoping (only the operator's own command sets this). */
56	  operatorAccepted?: boolean;
57	  /**
58	   * The passing verifier run that a `verified` status rests on, recorded on the then-current workspace. Nexus can
59	   * show that this run passed on these inputs; it cannot prove the verifier exercises this particular requirement.
60	   */
61	  verifiedBy?: { attempt: number; command: string; inputs: string; at: string };
62	  updatedAt: string;
63	}
64	
65	export interface ScopeChange {
66	  at: string;
67	  requirement: string;
68	  from: RequirementStatus;
69	  to: RequirementStatus;
70	  reason: string;
71	}
72	
73	export interface SteeringRecord {
74	  id: string;
75	  text: string;
76	  receivedAt: string;
77	  status: "queued" | "applied" | "cancelled";
78	  appliedAt?: string;
79	  appliedAtStep?: number;
80	}
81	
82	export interface VerificationAttempt {
83	  n: number;
84	  command: string;
85	  /** Candidate identity of the workspace the verifier ran on (tracked and untracked, non-ignored files). */
86	  inputs: string;
87	  /**
88	   * What else must be unchanged before a prior failure is reused: the agent process that ran it, the count of
89	   * mutating tool calls (any edit, write or shell command) at that time, and a fingerprint of inputs git ignores
90	   * (PATH, dependency install markers, .env files).
91	   */
92	  epoch?: string;
93	  mutationSeq?: number;
94	  external?: string;
95	  status: VerificationStatus | "SKIPPED_UNCHANGED_INPUTS";
96	  isDeliverableBound?: boolean;
97	  /** False when the run passed but nothing independent of the agent shows the change (see core/independent_check). */
98	  independent?: boolean;
99	  filtered?: boolean;
100	  at: string;
101	  /** First failing line of the verifier's output, when it failed. */
102	  failedCheck?: string;
103	}
104	
105	export interface ObjectiveOutcome {
106	  status: "completed" | "incomplete" | "blocked";
107	  reason: string;
108	  failedCheck?: string;
109	  remaining: string[];
110	  nextAction?: string;
111	  at: string;
112	}
113	
114	export interface ContinuationState {
115	  /** Segments of `segmentSteps` steps the current turn has run (1 for an ordinary turn). */
116	  segments: number;
117	  /** Steps run against this objective across turns. */
118	  totalSteps: number;
119	  /** Step (within the current turn) of the last observed progress. */
120	  lastProgressStep: number;
121	  stopReason?: string;
122	}
123	
124	export interface ObjectiveLedger {
125	  version: number;
126	  /** Work unit id when this ledger is scoped to a work unit in an operation or team (REQ-AGT-102/103). */
127	  unitId?: string;
128	  objective: string;
129	  objectiveSha256: string;
130	  startedAt: string;
131	  requirements: Requirement[];
132	  scopeChanges: ScopeChange[];
133	  steering: SteeringRecord[];
134	  verification: VerificationAttempt[];
135	  continuation: ContinuationState;
136	  /** The model's own statement of what comes next (update_requirements next_action). */
137	  nextAction?: string;
138	  outcome?: ObjectiveOutcome;
139	  /** Short follow-up messages the operator sent as new turns while this objective was unresolved. */
140	  amendments: Array<{ at: string; text: string }>;
141	  /**
142	   * Objective-scoped execution tracking (core/execution_tracking.ts): cumulative steps, progress, repetition,
143	   * failed approaches, interventions and compactions. Absent in ledgers written before it existed; `trackingOf` fills it.
144	   */
145	  execution?: ExecutionTracking;
146	}
147	
148	/** The ledger's execution tracking, created (or completed, for a ledger restored from an earlier version) on first use. */
149	export function trackingOf(ledger: ObjectiveLedger): ExecutionTracker {
150	  ledger.execution = normalizeTracking(ledger.execution);
151	  return new ExecutionTracker(ledger.execution);
152	}
153	
154	const now = () => new Date().toISOString();
155	const sha256 = (text: string) => createHash("sha256").update(text).digest("hex");
156	const clip = (text: string, max: number) => (text.length <= max ? text : `${text.slice(0, max - 1)}…`);
157	
158	/**
159	 * Acceptance criteria as written: top-level numbered items (`1.`, `2)`, `R3:`) of the objective. Each keeps its
160	 * heading line; the full wording stays in the verbatim objective. Fewer than two items means the objective is a
161	 * single request and is tracked as one requirement.
162	 */
163	export function seedRequirements(objective: string): Array<{ id: string; text: string; detail: string }> {
164	  const lines = objective.replace(/\r\n?/g, "\n").split("\n");
165	  const items: Array<{ indent: number; text: string; line: number }> = [];
166	  lines.forEach((line, index) => {
167	    const match = /^(\s*)(?:R?(\d{1,3})[.):]|R(\d{1,3})\s*[-–—])\s+(\S.*)$/.exec(line);
168	    if (match) items.push({ indent: match[1].replace(/\t/g, "    ").length, text: match[4].trim(), line: index });
169	  });
170	  const whole = [{ id: "R1", text: clip(firstLine(objective), MAX_REQUIREMENT_TEXT), detail: objective }];
171	  if (items.length < 2) return whole;
172	  // Only the outermost numbering level: nested numbered sub-steps belong to their parent item.
173	  const outer = Math.min(...items.map((item) => item.indent));
174	  const top = items.filter((item) => item.indent <= outer + 1);
175	  if (top.length < 2) return whole;
176	  // Each requirement's full wording: from its own line up to the next top-level item (the last runs to the end).
177	  return top.map((item, index) => ({
178	    id: `R${index + 1}`,
179	    text: clip(item.text, MAX_REQUIREMENT_TEXT),
180	    detail: lines.slice(item.line, index + 1 < top.length ? top[index + 1].line : lines.length).join("\n").trimEnd(),
181	  }));
182	}
183	
184	function firstLine(text: string): string {
185	  return text.split("\n").map((line) => line.trim()).find(Boolean) ?? text.trim();
186	}
187	
188	export function createLedger(objective: string, at = now(), unitId?: string): ObjectiveLedger {
189	  return {
190	    version: LEDGER_VERSION,
191	    ...(unitId ? { unitId } : {}),
192	    objective,
193	    objectiveSha256: sha256(objective),
194	    startedAt: at,
195	    requirements: seedRequirements(objective).map((seed) => ({
196	      ...seed,
197	      status: "open" as const,
198	      source: "objective" as const,
199	      evidence: [],
200	      updatedAt: at,
201	    })),
202	    scopeChanges: [],
203	    steering: [],
204	    verification: [],
205	    continuation: { segments: 1, totalSteps: 0, lastProgressStep: 0 },
206	    amendments: [],
207	    execution: createTracking(),
208	  };
209	}
210	
211	/**
212	 * Requirements an operator follow-up adds to the objective it continues: its numbered items, appended after the
213	 * existing ones (an amendment never removes or rewrites what was asked before).
214	 */
215	export function amendObjective(ledger: ObjectiveLedger, prompt: string, at = now()): Requirement[] {
216	  ledger.amendments.push({ at, text: prompt });
217	  const seeds = seedRequirements(prompt);
218	  if (seeds.length < 2) return [];
219	  const base = ledger.requirements.filter((r) => r.source === "objective").length;
220	  const added = seeds.map((seed, i) => ({
221	    id: `R${base + i + 1}`,
222	    text: seed.text,
223	    detail: seed.detail,
224	    status: "open" as const,
225	    source: "objective" as const,
226	    evidence: [],
227	    note: `added by the operator's follow-up of ${at}`,
228	    updatedAt: at,
229	  }));
230	  ledger.requirements.push(...added);
231	  return added;
232	}
233	
234	/**
235	 * Whether the operator's next message starts a new objective or continues the unresolved one. A message that
236	 * carries its own numbered requirements, or is long, is a new objective; a short message ("continue", "also check
237	 * the README") while requirements remain open amends the current one. A resolved objective is always replaced.
238	 */
239	export function isNewObjective(ledger: ObjectiveLedger | undefined, prompt: string): boolean {
240	  if (!ledger || ledger.outcome?.status === "completed") return true;
241	  // A single request without listed requirements does not chain, except where the operator explicitly continues it
242	  // ("continue", "keep going", "try again"): that is the same objective, and keeps its execution history.
243	  if (gatingRequirements(ledger).length === 0) return !isContinuationPrompt(prompt);
244	  // A structured objective not yet completed is never replaced implicitly, whatever the follow-up looks like (a
245	  // detailed correction is still a correction). The operator replaces it explicitly: `/requirements clear` or `/clear`.
246	  return false;
247	}
248	
249	/**
250	 * A follow-up that only asks the work to go on ("continue", "keep going", "resume", "try again", optionally with a
251	 * short qualifier such as "continue please" or "go on from where you stopped"). Anything that states new work is not.
252	 */
253	export function isContinuationPrompt(prompt: string): boolean {
254	  const normalized = prompt.trim().toLowerCase();
255	  let end = normalized.length;
256	  while (end > 0) {
257	    const code = normalized.charCodeAt(end - 1);
258	    if (code === 33 || code === 46 || code === 0x2026) end--;
259	    else break;
260	  }
261	  const text = end === normalized.length ? normalized : normalized.slice(0, end);
262	  if (!text || text.length > 80 || text.includes("\n")) return false;
263	  return /^(?:please\s+)?(?:continue|keep going|keep at it|go on|go ahead|carry on|resume|proceed|try again|retry|next|finish(?: it| the task| the job)?|ok(?:ay)?,?\s+continue)\b(?:[\s,]+(?:please|then|now|on|with (?:it|the task|the work)|where you (?:left off|stopped)|from where you (?:left off|stopped)))*$/.test(text);
264	}
265	
266	/** Requirements that gate completion: seeded from a structured objective (two or more), or added explicitly. */
267	export function gatingRequirements(ledger: ObjectiveLedger): Requirement[] {
268	  const seeded = ledger.requirements.filter((r) => r.source === "objective");
269	  const structured = seeded.length >= 2;
270	  return ledger.requirements.filter((r) => r.source !== "objective" || structured);
271	}
272	
273	export function openRequirements(ledger: ObjectiveLedger): Requirement[] {
274	  return gatingRequirements(ledger).filter((r) => !DONE_STATUSES.has(r.status) && r.status !== "blocked");
275	}
276	
277	/** Blocked requirements, and operator requirements the agent descoped without the operator's acceptance. */
278	export function blockedRequirements(ledger: ObjectiveLedger): Requirement[] {
279	  return gatingRequirements(ledger).filter((r) => r.status === "blocked" || (r.status === "descoped" && !requirementDone(r)));
280	}
281	
282	/**
283	 * The operator's acceptance of descoped requirements (`/requirements accept R2 R3`). Returns the ids accepted and
284	 * the ids refused (unknown, or not descoped).
285	 */
286	export function acceptDescoping(ledger: ObjectiveLedger, ids: string[], at = now()): { accepted: string[]; refused: string[] } {
287	  const accepted: string[] = [];
288	  const refused: string[] = [];
289	  for (const id of ids) {
290	    const r = ledger.requirements.find((req) => req.id.toLowerCase() === id.toLowerCase());
291	    if (!r || r.status !== "descoped") {
292	      refused.push(id);
293	      continue;
294	    }
295	    r.operatorAccepted = true;
296	    r.updatedAt = at;
297	    ledger.scopeChanges.push({ at, requirement: r.id, from: "descoped", to: "descoped", reason: "accepted by the operator" });
298	    accepted.push(r.id);
299	  }
300	  return { accepted, refused };
301	}
302	
303	export function hasOpenRequirements(ledger: ObjectiveLedger): boolean {
304	  return openRequirements(ledger).length > 0 || blockedRequirements(ledger).length > 0;
305	}
306	
307	export interface RequirementUpdate {
308	  id?: string;
309	  /** New requirement text (adds a model-sourced requirement when `id` is absent or unknown). */
310	  text?: string;
311	  status?: RequirementStatus;
312	  evidence?: string[] | string;
313	  note?: string;
314	}
315	
316	export interface UpdateResult {
317	  ok: boolean;
318	  changed: boolean;
319	  errors: string[];
320	}
321	
322	/**
323	 * Applies the model's requirement updates. Seeded and steering requirements cannot be removed or reworded; moving
324	 * one to `descoped` or `blocked` needs a reason and is recorded as a scope change; `implemented` and `verified` need
325	 * evidence. Invalid entries are rejected individually, so one mistake does not discard the rest.
326	 */
327	export function applyRequirementUpdates(
328	  ledger: ObjectiveLedger,
329	  updates: RequirementUpdate[],
330	  nextAction?: string,
331	  at = now(),
332	  /** The passing verifier attempt on the current workspace, if one is recorded (required for `verified`). */
333	  currentPass?: VerificationAttempt,
334	): UpdateResult {
335	  const errors: string[] = [];
336	  let changed = false;
