423	        changed = true;
424	      }
425	    }
426	    if (requirement.evidence.length > MAX_EVIDENCE_ITEMS) requirement.evidence = requirement.evidence.slice(-MAX_EVIDENCE_ITEMS);
427	    requirement.updatedAt = at;
428	  }
429	  if (typeof nextAction === "string" && nextAction.trim() && nextAction.trim() !== ledger.nextAction) {
430	    ledger.nextAction = clip(nextAction.trim(), MAX_EVIDENCE_CHARS);
431	    changed = true;
432	  }
433	  return { ok: errors.length === 0, changed, errors };
434	}
