436	export function queueSteering(ledger: ObjectiveLedger, id: string, text: string, at = now()): SteeringRecord | undefined {
437	  if (ledger.steering.some((s) => s.id === id)) return undefined;
438	  const record: SteeringRecord = { id, text, receivedAt: at, status: "queued" };
439	  ledger.steering.push(record);
440	  return record;
