501	/**
502	 * The context block the model sees every request: requirement states, steering, verification and continuation.
503	 * The objective is included verbatim only when the operator's original message is no longer in the conversation.
504	 */
505	export function renderPinnedLedger(
506	  ledger: ObjectiveLedger,
507	  includeObjective: boolean,
508	  budgetChars = MAX_PINNED_OBJECTIVE_CHARS,
509	  recovery: RecoveryContextOptions = {},
510	): string {
511	  const out: string[] = [PINNED_LEDGER_PREFIX];
512	  if (includeObjective) {
513	    const unresolved = gatingRequirements(ledger).filter((r) => !requirementDone(r));
514	    if (ledger.objective.length <= budgetChars) {
515	      out.push("Operator objective (verbatim; the original message left the context):", ledger.objective);
516	    } else {
517	      // Too large to repeat on every request. Every unresolved requirement's complete wording is carried instead;
518	      // what does not fit is named, and read_objective returns any part verbatim.
519	      out.push(
520	        `Operator objective (${ledger.objective.length} chars; the original message left the context and the whole text exceeds this block's budget). ` +
521	          "The complete wording of each unresolved requirement follows; call read_objective (requirement id, or offset/length) for any other part, verbatim.",
522	      );
523	      let room = budgetChars;
524	      const intro = ledger.objective.slice(0, Math.min(1500, ledger.objective.length));
525	      out.push("Opening of the objective:", intro);
526	      room -= intro.length;
527	      const deferred: string[] = [];
528	      for (const r of unresolved) {
529	        const detail = r.detail ?? r.text;
530	        if (detail.length <= room) {
531	          out.push(`Full text of ${r.id} [${r.status}]:`, detail);
532	          room -= detail.length;
533	        } else {
534	          deferred.push(r.id);
535	        }
536	      }
537	      if (deferred.length) out.push(`Not shown here for space (unresolved; fetch with read_objective before working on them): ${deferred.join(", ")}.`);
538	    }
539	  } else {
540	    out.push(`Operator objective: the operator's original message in this conversation (sha256 ${ledger.objectiveSha256.slice(0, 12)}).`);
541	  }
542	  // Operator follow-ups and steering are carried verbatim, newest first within their budget; what does not fit is named
543	  // with its size and read_objective returns it in full.
544	  const steering = ledger.steering.filter((s) => s.status !== "cancelled");
545	  const operatorMessages = [
546	    ...ledger.amendments.map((a, i) => ({ key: `amendment:${i}`, at: a.at, size: a.text.length })),
547	    ...steering.map((s) => ({ key: `steering:${s.id}`, at: s.receivedAt, size: s.text.length })),
548	  ].sort((a, b) => b.at.localeCompare(a.at));
549	  let operatorRoom = Math.min(MAX_PINNED_OPERATOR_CHARS, budgetChars);
550	  const verbatim = new Set<string>();
551	  for (const m of operatorMessages) {
552	    if (m.size > operatorRoom) continue;
553	    verbatim.add(m.key);
554	    operatorRoom -= m.size;
555	  }
556	  const operatorEntry = (key: string, label: string, text: string, fetch: string) =>
557	    verbatim.has(key)
558	      ? `- ${label} ${text}`
559	      : `- ${label} (${text.length} chars, not shown for space; read_objective ${fetch} returns it verbatim): ${clip(text.replace(/\s+/g, " "), 120)}`;
560	  if (ledger.amendments.length) {
561	    out.push("Operator follow-ups on this objective:");
562	    ledger.amendments.forEach((a, i) => out.push(operatorEntry(`amendment:${i}`, `A${i + 1}`, a.text, `amendment "A${i + 1}"`)));
563	  }
564	  const gating = gatingRequirements(ledger);
565	  if (gating.length) {
566	    out.push("Acceptance requirements (the plan never replaces these; update them with update_requirements and evidence):");
567	    for (const r of gating) {
568	      const evidence = r.evidence.length ? ` evidence: ${r.evidence.join("; ")}` : "";
569	      const note = r.note ? ` note: ${r.note}` : "";
570	      const pending = r.status === "descoped" && !requirementDone(r) ? " (descoped by you; still unresolved until the operator accepts it)" : "";
571	      out.push(`- ${r.id} [${r.status}${pending}] ${r.text}${evidence}${note}`);
572	    }
573	  }
574	  if (ledger.scopeChanges.length) {
575	    out.push("Explicit scope changes:");
576	    for (const change of ledger.scopeChanges.slice(-8)) out.push(`- ${change.requirement}: ${change.from} -> ${change.to} (${change.reason})`);
577	  }
578	  if (steering.length) {
579	    out.push("Operator steering received during the work (applies on top of the objective):");
580	    for (const s of steering) {
581	      out.push(operatorEntry(`steering:${s.id}`, `${s.id} [${s.status}${s.appliedAtStep ? ` at step ${s.appliedAtStep}` : ""}]`, s.text, `steering "${s.id}"`));
582	    }
583	  }
584	  const attempts = ledger.verification.slice(-3);
585	  if (attempts.length) {
586	    out.push("Verifier attempts (inputs = workspace candidate identity):");
587	    for (const a of attempts) out.push(`- #${a.n} ${a.command} -> ${a.status} on ${a.inputs.slice(0, 12)}${a.failedCheck ? ` (${a.failedCheck})` : ""}`);
588	  }
589	  const c = ledger.continuation;
590	  if (c.segments > 1 || c.totalSteps > 0) {
591	    out.push(`Continuation: segment ${c.segments} of this turn; ${c.totalSteps} steps so far on this objective. Keep working toward the open requirements; no operator "continue" is needed.`);
592	  }
593	  if (ledger.execution) {
594	    // A ledger restored from an earlier version may lack fields (recovery, coverage): read a normalized copy.
595	    const execution = normalizeTracking(ledger.execution);
596	    const tracker = new ExecutionTracker(execution);
597	    if (tracker.recoveryStage === "constrained") out.push(renderRecoveryContext(recoveryInput(ledger), recovery));
598	    const loops = tracker.loops().slice(0, 3);
599	    if (loops.length) {
600	      out.push("Repeated without progress on an unchanged workspace (do not repeat these; change approach):");
601	      for (const r of loops) out.push(`- ${r.action} ×${r.count} (steps ${r.firstStep}-${r.lastStep}) -> ${r.outcome.slice(0, 160)}`);
602	    }
603	    const failed = execution.failedApproaches.slice(-4);
604	    if (failed.length) {
605	      out.push("Failed approaches on this objective (most recent):");
606	      for (const f of failed) out.push(`- step ${f.step}: ${f.detail.slice(0, 200)}`);
607	    }
608	  }
609	  if (ledger.nextAction) out.push(`Next action (your last statement): ${ledger.nextAction}`);
610	  return out.join("\n");
611	}
