687	export function recoveryInput(ledger: ObjectiveLedger): { objective: string; open: Array<{ id: string; text: string }>; execution: ExecutionTracking } {
688	  return { objective: ledger.objective, open: gatingRequirements(ledger).filter((q) => !requirementDone(q)), execution: normalizeTracking(ledger.execution) };
