691	/** Whether the ledger has anything worth a context block beyond the operator's message itself. */
692	export function ledgerNeedsPinning(ledger: ObjectiveLedger, objectiveInContext: boolean): boolean {
693	  const execution = ledger.execution;
694	  return (
695	    !objectiveInContext ||
696	    (execution !== undefined && (execution.recovery?.stage ?? "normal") !== "normal") ||
697	    gatingRequirements(ledger).length > 0 ||
698	    ledger.steering.length > 0 ||
699	    ledger.verification.length > 0 ||
700	    ledger.continuation.segments > 1 ||
701	    ledger.amendments.length > 0
702	  );
703	}
