705	/** Requirement rows for receipts and exports. */
706	export function requirementRows(ledger: ObjectiveLedger): Array<[string, string]> {
707	  return gatingRequirements(ledger).map((r) => {
708	    const status =
709	      r.status === "descoped"
710	        ? requirementDone(r) ? "DESCOPED (accepted)" : "DESCOPED (needs operator acceptance)"
711	        : r.status === "implemented"
712	          ? "IMPLEMENTED (model-reported)"
713	          : r.status === "verified" && r.verifiedBy
714	            ? `VERIFIED (verifier #${r.verifiedBy.attempt} ${r.verifiedBy.command} passed on ${r.verifiedBy.inputs.slice(0, 12)})`
715	            : r.status.toUpperCase();
716	    return [r.id, `${status} ${r.text}${r.note ? ` (${r.note})` : ""}`];
717	  });
718	}
