793	/** What read_objective returns for `args`. */
794	export function readObjective(
795	  ledger: ObjectiveLedger,
796	  args: { requirement?: unknown; steering?: unknown; amendment?: unknown; offset?: unknown; length?: unknown },
797	): { ok: boolean; text: string } {
798	  if (typeof args.steering === "string" && args.steering.trim()) {
799	    const id = args.steering.trim();
800	    const s = ledger.steering.find((record) => record.id === id);
801	    if (!s) return { ok: false, text: `No steering ${id}; known: ${ledger.steering.map((record) => record.id).join(", ") || "none"}.` };
802	    return { ok: true, text: `Operator steering ${s.id} [${s.status}] received ${s.receivedAt}\n${s.text}` };
803	  }
804	  if (typeof args.amendment === "string" && args.amendment.trim()) {
805	    const id = args.amendment.trim();
806	    const n = Number(/^A(\d+)$/i.exec(id)?.[1] ?? 0);
807	    const a = n > 0 ? ledger.amendments[n - 1] : undefined;
808	    if (!a) return { ok: false, text: `No follow-up ${id}; known: ${ledger.amendments.length ? `A1-A${ledger.amendments.length}` : "none"}.` };
809	    return { ok: true, text: `Operator follow-up A${n} received ${a.at}\n${a.text}` };
810	  }
811	  if (typeof args.requirement === "string" && args.requirement.trim()) {
812	    const r = ledger.requirements.find((req) => req.id.toLowerCase() === String(args.requirement).trim().toLowerCase());
813	    if (!r) return { ok: false, text: `No requirement ${String(args.requirement)}; known: ${ledger.requirements.map((req) => req.id).join(", ")}.` };
814	    return { ok: true, text: `${r.id} [${r.status}]\n${r.detail ?? r.text}` };
815	  }
816	  const total = ledger.objective.length;
817	  const offset = Math.max(0, Math.min(total, Math.floor(Number(args.offset ?? 0)) || 0));
818	  const length = Math.max(1, Math.min(20_000, Math.floor(Number(args.length ?? 20_000)) || 20_000));
819	  const end = Math.min(total, offset + length);

