621	const clipText = (text: string, max: number) => (text.length <= max ? text : `${text.slice(0, max - 1)}…`);
622	const fmtRanges = (ranges: Array<[number, number]>) => ranges.map(([a, b]) => (b < a ? "empty" : a === b ? `${a}` : `${a}-${b}`)).join(", ");
623	
624	/**
625	 * The RECOVERY_REQUIRED context: built only from recorded evidence (executed observations, the ledger, recovery
626	 * state), never from the model's own claims. When the specific open question is not recorded, it says so and requires
627	 * the agent to state it. `present` (when the caller has the conversation) marks evidence still in context.
628	 */
629	export function renderRecoveryContext(
630	  input: { objective: string; open: Array<{ id: string; text: string }>; execution: ExecutionTracking },
631	  opts: RecoveryContextOptions = {},
632	): string {
633	  const t = normalizeTracking(input.execution);
634	  const tracker = new ExecutionTracker(t);
635	  const r = t.recovery;
636	  const state = r.state ?? "unknown";
637	  const out: string[] = ["RECOVERY_REQUIRED"];
638	  out.push("Current objective:", `- ${clipText(input.objective.replace(/\s+/g, " "), 300)}`);
639	  const observed = state === "unknown" ? [] : tracker.observedOn(state).sort((a, b) => Math.max(...b.steps) - Math.max(...a.steps)).slice(0, 8);
640	  out.push("Previously acquired evidence (on the current workspace state):");
641	  if (observed.length) {
642	    for (const o of observed) {
643	      const live = opts.present ? (o.keys.some((k) => opts.present!(k)) ? "output still in this conversation" : "output no longer in this conversation") : `step(s) ${o.steps.slice(-4).join(", ")}`;
644	      out.push(`- ${o.path} lines ${fmtRanges(o.ranges)}${o.total !== undefined ? ` of ${o.total}` : ""} (${live}; fingerprint ${o.fingerprints.slice(-1)[0]})`);
645	    }
646	  } else out.push("- none recorded as file line ranges");
647	  const repeated = [
648	    ...(state === "unknown" ? [] : tracker.equivalentsOn(state).slice(0, 4).map((e) => `- ${e.path}${e.start !== undefined ? ` lines ${e.start}-${e.end}` : ""}: obtained again ${e.count} time(s) while already in this conversation (steps ${e.firstStep}-${e.lastStep}; last: ${e.action})`)),
649	    ...tracker.loops().filter((l) => l.state === state).slice(0, 3).map((l) => `- ${l.action} ×${l.count} with the same result (steps ${l.firstStep}-${l.lastStep})`),
650	  ];
651	  out.push("Repeated observations:", ...(repeated.length ? repeated : [`- ${r.trigger ?? "unrecorded"}`]));
652	  const unchangedSince = t.progress.filter((p) => /workspace reached a new state/.test(p.detail)).at(-1)?.step;
653	  out.push("Current workspace state:", `- ${state === "unknown" ? "unknown" : state.slice(0, 12)}${unchangedSince ? `; unchanged since step ${unchangedSince}` : ""}`);
654	  const last = t.progress.at(-1);
655	  out.push("Last meaningful progress:", `- ${last ? `step ${last.step}: ${last.detail}` : "none recorded on this objective"}`);
656	  const open = input.open.slice(0, 4);
657	  out.push("Unresolved question:");
658	  for (const q of open) out.push(`- open requirement ${q.id}: ${clipText(q.text, 160)}`);
659	  out.push("- The specific question your next action must answer is not recorded. State it in one sentence, and why the evidence above does not answer it, before any further observation.");
660	  out.push(
661	    "Disallowed operations (refused before they run while the workspace is unchanged):",
662	    "- Reading any of the line ranges above again, through any interface (read_file, batch_read, cat/head/sed), while that output is still in this conversation.",
663	    "- (Other calls are not refused, but repeating one that returns the same result on this unchanged workspace stops the turn.)",
664	  );
665	  // Only actions the agent may take: a restricted role or read-only mode refuses the others at dispatch.
666	  const can = opts.permits ?? (() => true);
667	  const canAny = (...tools: string[]) => tools.some(can);
668	  const actions = [
669	    "use the output already in this conversation",
670	    ...(canAny("read_file", "batch_read") ? ["read lines or files not listed above"] : []),
671	    ...(canAny("search_code", "search_symbols") ? ["search for a specific symbol or string"] : []),
672	    ...(canAny("write_file", "edit_file", "patch_file") ? ["edit files"] : []),
673	    ...(canAny("run_command", "run_tests") ? ["run a build, test or command"] : []),
674	  ].join("; ");
675	  out.push(
676	    "Permitted next actions:",
677	    `- ${actions.charAt(0).toUpperCase()}${actions.slice(1)};`,
678	    `- ${can("update_requirements") ? "record a finding or a blocker with update_requirements (status \"blocked\" with the reason); or " : ""}finish with a final message reporting what you found.`,
679	  );
680	  const remaining = Math.max(0, r.allowedDenials - r.denials);
681	  const stagnation = opts.stagnationSteps !== undefined ? `; ${Math.max(0, opts.stagnationSteps - t.stepsWithoutProgress)} step(s) without progress left before the turn stops` : "";
682	  out.push("Recovery budget:", `- ${remaining} refusal(s) left of ${r.allowedDenials} in episode ${r.episode}; another refused attempt beyond that stops the turn${stagnation}.`);
683	  return out.join("\n");
684	}
