describe("verified means a recorded passing verifier run on the current workspace", () => {
  test("verified without a current pass is refused; after a passing run_tests it binds that run; a later change demotes it", { timeout: 60_000 }, async () => {
    const repo = makeRepo({
      "importer.mjs": 'export function imported() { return false; }\n',
      "test/importer.test.mjs": [
        'import { test } from "node:test";',
        'import assert from "node:assert/strict";',
        'import { imported } from "../importer.mjs";',
        'test("importer works", () => assert.equal(imported(), true));',
        "",
      ].join("\n"),
      Makefile: ".PHONY: test\ntest:\n\t@env -u NODE_TEST_CONTEXT node --test test/importer.test.mjs\n",
    });
    const script = (n: number): Reply =>
      n === 1
        ? { kind: "tools", calls: [{ name: "update_requirements", args: { requirements: [{ id: "R1", status: "verified", evidence: ["I checked it"] }] } }] }
        : n === 2
          ? { kind: "tools", calls: [{ name: "write_file", args: { path: "importer.mjs", content: "export function imported() { return true; }\n", overwrite: true } }] }
          : n === 3
            ? { kind: "tools", calls: [{ name: "run_tests", args: {} }] }
            : n === 4
              ? { kind: "tools", calls: [{ name: "update_requirements", args: { requirements: [{ id: "R1", status: "verified", evidence: ["importer.mjs"] }] } }] }
            : n === 5
              ? write("later-change.txt")
              : text("stopping");
    const gw = await startGateway(script);
    const agent = quiet(new AutonomousAgent(cfg(gw.url, repo, {
      authoritativeVerifierCommand: "make test",
      trustedDeliverableFiles: ["importer.mjs"],
      continuation: { ...DEFAULT_CONTINUATION, maxCompletionNudges: 0 },
    })));
    try {
      await agent.runTurn(OBJECTIVE);
      const refusal = (gw.requests[1] as any).messages.filter((m: any) => m.role === "tool" && m.name === "update_requirements").at(-1);
      assert.match(refusal.content, /verified needs a passing verifier run on the current workspace/);
      const ledger = agent.getObjective()!;
      const pass = ledger.verification.find((a) => a.status === "PASSED");
      assert.ok(pass, "run_tests recorded a verifier attempt");
      const r1 = ledger.requirements[0];
      assert.equal(r1.status, "implemented", "the later write demoted it");
      assert.match(r1.note ?? "", /verification invalidated: write_file changed the workspace after the verifier run \(was verifier #\d+\)/);
      assert.ok(r1.evidence.some((e) => e.startsWith(`verifier #${pass!.n}: `)), "the bound receipt stays in the evidence trail");
    } finally {
      agent.shutdown();
      await gw.close();
      fs.rmSync(repo, { recursive: true, force: true });
    }
  });

  test("receipt rows distinguish model-reported implementation from bound verification", () => {
    const ledger = createLedger(OBJECTIVE);
    applyRequirementUpdates(ledger, [{ id: "R1", status: "implemented", evidence: ["a.ts"] }]);
    const pass = { n: 4, command: "make test", inputs: "abcdef1234567890", status: "PASSED" as const, at: "t" };
    applyRequirementUpdates(ledger, [{ id: "R2", status: "verified", evidence: ["b.ts"] }], undefined, undefined, pass);
    const rows = Object.fromEntries(require_rows(ledger));
    assert.match(rows.R1, /^IMPLEMENTED \(model-reported\)/);
    assert.match(rows.R2, /^VERIFIED \(verifier #4 make test passed on abcdef123456\)/);
    assert.deepEqual(invalidateVerified(ledger, "edit"), ["R2"]);
  });
});

/**
 * `/requirements`: the acceptance requirements of the current objective. `accept <id>...` is the operator's authority
 * to let a requirement the agent descoped count as done; the agent cannot do this itself.
 */
async function requirements({ host, args }: SlashContext): Promise<SlashOutcome> {
  const { acceptDescoping, requirementRows } = await import("../core/objective.js");
  const ledger = host.app.getAgent().getObjective();
  if (!ledger) return reply("requirements", "No objective is being tracked yet.");
  const [verb, ...ids] = args.split(/\s+/).filter(Boolean);
  let note = "";
  if (verb === "clear") {
    const dropped = host.app.getAgent().clearObjective();
    host.saveSession();
    const open = dropped ? requirementRows(dropped).filter(([, v]) => !/^(IMPLEMENTED|VERIFIED|DESCOPED \(accepted\))/.test(v)).map(([id]) => id) : [];
    return reply("requirements", `The objective is cleared${open.length ? ` (unresolved when cleared: ${open.join(", ")})` : ""}; your next message starts a new one.`);
  }
  if (verb === "accept") {
    if (!ids.length) return reply("requirements", "Name the requirements to accept, e.g. /requirements accept R2.", false);
    const { accepted, refused } = acceptDescoping(ledger, ids);
    if (accepted.length) host.saveSession();
    note = `${accepted.length ? `Accepted the descoping of ${accepted.join(", ")}.` : ""}${refused.length ? ` Not descoped (nothing to accept): ${refused.join(", ")}.` : ""}\n\n`;
  } else if (verb) {
    return reply("requirements", "Usage: /requirements [accept <id>...|clear]", false);
  }
  const rows = requirementRows(ledger);
  if (!rows.length) return reply("requirements", `${note}The objective is a single request; no separate acceptance requirements were listed.`);
  return reply("requirements", `${note}${rows.map(([id, value]) => `${id.padEnd(4)} ${value}`).join("\n")}`);
}

/** Context sizing and counting: limits with their sources, capability state, the last request's count and source. */
function sizingRows(agent: AutonomousAgent): Array<[string, string]> {
  const caps = agent.getProviderCapabilities();
  const last = agent.getLastRequestCount();
  const tracking = agent.getObjective()?.execution;
  const rows: Array<[string, string]> = [];
  const via = caps?.advertised?.via ? ` via ${caps.advertised.via}` : "";

